import { useState } from 'react';
import Navbar from '../components/Navbar';
import TransactionForm from '../components/TransactionForm';
import TransactionList from '../components/TransactionList';
import SummaryCard from '../components/SummaryCard';
import InvestmentForm from '../components/InvestmentForm';
import InvestmentList from '../components/InvestmentList';
import Tabs from '../components/Tabs';
import styles from './Dashboard.module.css';

const Dashboard = () => {
  const [transactions, setTransactions] = useState([]); // Normal transactions
  const [investments, setInvestments] = useState([]); // Investments
  const [activeTab, setActiveTab] = useState(0);
  const [currentBalance, setCurrentBalance] = useState(310000); // Initial balance

  // Calculate total income, total expenses, and balance
  const totalIncome = transactions
    .filter((t) => t.type === 'income')
    .reduce((sum, t) => sum + parseFloat(t.amount || 0), 0);

  const totalExpenses = transactions
    .filter((t) => t.type === 'expense')
    .reduce((sum, t) => sum + parseFloat(t.amount || 0), 0);

  // Calculate investment income and expenses
  const investmentIncome = investments.reduce(
    (sum, inv) => sum + (parseFloat(inv.salePrice) - parseFloat(inv.initialCost || 0)),
    0
  );

  const investmentExpenses = investments.reduce(
    (sum, inv) => sum + parseFloat(inv.initialCost || 0),
    0
  );

  // Totals including investments
  const totalIncomeWithInvestments = totalIncome + investmentIncome;
  const totalExpensesWithInvestments = totalExpenses + investmentExpenses;
  const balance = totalIncomeWithInvestments - totalExpensesWithInvestments;

  // Function to add a new transaction
  const handleAddTransaction = (transaction) => {
    const newTransaction = { ...transaction, amount: parseFloat(transaction.amount) };
    setTransactions((prev) => [...prev, newTransaction]);

    // Update current balance
    setCurrentBalance((prev) => {
      return newTransaction.type === 'income'
        ? prev + newTransaction.amount
        : prev - newTransaction.amount;
    });
  };

  // Function to add a new investment
  const handleAddInvestment = (investment) => {
    const newInvestment = {
      ...investment,
      initialCost: parseFloat(investment.initialCost),
      salePrice: parseFloat(investment.salePrice),
    };
    setInvestments((prev) => [...prev, newInvestment]);

    // Register initial cost as an expense
    handleAddTransaction({
      description: `Purchase of laptop (${investment.brand})`,
      amount: newInvestment.initialCost,
      type: 'expense',
    });

    // Register profit as income
    const profit = newInvestment.salePrice - newInvestment.initialCost;
    if (profit > 0) {
      handleAddTransaction({
        description: `Profit from laptop (${investment.brand})`,
        amount: profit,
        type: 'income',
      });
    }
  };

  const handleEditInvestment = (index) => {
    console.log('Edit investment:', investments[index]);
  };

  // Define tabs
  const tabs = ['Summary', 'Transactions', 'Investments'];

  return (
    <div>
      <Navbar />
      <div className={styles.dashboard}>
        <h1>Business Control</h1>
        <Tabs tabs={tabs} activeTab={activeTab} onTabChange={setActiveTab} />

        {activeTab === 0 && (
          <div className={styles.summaryCard}>
            <SummaryCard
              totalIncome={totalIncomeWithInvestments}
              totalExpenses={totalExpensesWithInvestments}
              balance={balance}
              currentBalance={currentBalance}
            />
          </div>
        )}

        {activeTab === 1 && (
          <div className={styles.transactionSection}>
            <h2>Transactions</h2>
            <TransactionForm onAddTransaction={handleAddTransaction} />
            <TransactionList transactions={transactions} />
          </div>
        )}

{activeTab === 2 && (
          <div className={styles.investmentSection}>
            <h2>Investments in Laptops</h2>
            <InvestmentForm onAddInvestment={handleAddInvestment} />
            <InvestmentList
              investments={investments}
              onEditInvestment={handleEditInvestment}
            />
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
